const upsertPendingPriceSuggestion = `-- name: UpsertPendingPriceSuggestion :one
INSERT INTO price_suggestions (event_id, zone_id, current_price, suggested_price, reason, metrics)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (event_id, zone_id) WHERE status = 'PENDING'
DO UPDATE SET current_price   = EXCLUDED.current_price,
              suggested_price = EXCLUDED.suggested_price,
              reason          = EXCLUDED.reason,
              metrics         = EXCLUDED.metrics,
              created_at      = now()
RETURNING id, event_id, zone_id, current_price, suggested_price, reason, metrics, status, reviewed_by, reviewed_at, created_at
`

type UpsertPendingPriceSuggestionParams struct {
	EventID        pgtype.UUID    `json:"event_id"`
	ZoneID         pgtype.UUID    `json:"zone_id"`
	CurrentPrice   pgtype.Numeric `json:"current_price"`
	SuggestedPrice pgtype.Numeric `json:"suggested_price"`
	Reason         string         `json:"reason"`
	Metrics        []byte         `json:"metrics"`
}

func (q *Queries) UpsertPendingPriceSuggestion(ctx context.Context, arg UpsertPendingPriceSuggestionParams) (PriceSuggestion, error) {
	row := q.db.QueryRow(ctx, upsertPendingPriceSuggestion,
		arg.EventID,
		arg.ZoneID,
		arg.CurrentPrice,
		arg.SuggestedPrice,
		arg.Reason,
		arg.Metrics,
	)
	var i PriceSuggestion
	err := row.Scan(
		&i.ID,
		&i.EventID,
		&i.ZoneID,
		&i.CurrentPrice,
		&i.SuggestedPrice,
		&i.Reason,
		&i.Metrics,
		&i.Status,
		&i.ReviewedBy,
		&i.ReviewedAt,
		&i.CreatedAt,
	)
	return i, err
}

